-- Migration 035: WASSCE Biology 2023 Questions (50 questions)
-- Properly linked to past_paper_id

INSERT OR IGNORE INTO questions (id, topic_id, subject_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, time_limit) VALUES
-- Cell Biology (10 questions)
('q_wassce_bio_2023_01', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The organelle responsible for protein synthesis in cells is the:', 'multiple_choice', '["A. Mitochondria", "B. Ribosome", "C. Golgi apparatus", "D. Lysosome"]', 'B', 'Ribosomes are the sites of protein synthesis in cells.', 'easy', 1, 60),
('q_wassce_bio_2023_02', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Which of the following is NOT a function of the cell membrane?', 'multiple_choice', '["A. Selective permeability", "B. Protection", "C. Protein synthesis", "D. Cell recognition"]', 'C', 'Protein synthesis occurs at ribosomes, not the cell membrane.', 'easy', 1, 60),
('q_wassce_bio_2023_03', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The powerhouse of the cell is the:', 'multiple_choice', '["A. Nucleus", "B. Chloroplast", "C. Mitochondria", "D. Endoplasmic reticulum"]', 'C', 'Mitochondria produce ATP through cellular respiration.', 'easy', 1, 60),
('q_wassce_bio_2023_04', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Osmosis is the movement of:', 'multiple_choice', '["A. Solute from low to high concentration", "B. Water from high to low water potential", "C. Solute through a membrane", "D. Gases across a membrane"]', 'B', 'Osmosis is water movement from high to low water potential through a semi-permeable membrane.', 'medium', 1, 90),
('q_wassce_bio_2023_05', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Which organelle contains digestive enzymes?', 'multiple_choice', '["A. Ribosome", "B. Lysosome", "C. Centrosome", "D. Nucleolus"]', 'B', 'Lysosomes contain hydrolytic enzymes for intracellular digestion.', 'easy', 1, 60),
('q_wassce_bio_2023_06', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The control center of the cell is the:', 'multiple_choice', '["A. Cytoplasm", "B. Cell membrane", "C. Nucleus", "D. Mitochondria"]', 'C', 'The nucleus contains DNA and controls cell activities.', 'easy', 1, 60),
('q_wassce_bio_2023_07', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Active transport differs from passive transport because it:', 'multiple_choice', '["A. Does not require a membrane", "B. Requires energy (ATP)", "C. Only moves water", "D. Moves substances down a gradient"]', 'B', 'Active transport requires ATP to move substances against concentration gradient.', 'medium', 1, 90),
('q_wassce_bio_2023_08', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Plant cells differ from animal cells by having:', 'multiple_choice', '["A. Mitochondria", "B. Cell wall and chloroplasts", "C. Nucleus", "D. Ribosomes"]', 'B', 'Plant cells have cell walls and chloroplasts that animal cells lack.', 'easy', 1, 60),
('q_wassce_bio_2023_09', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The fluid mosaic model describes the structure of:', 'multiple_choice', '["A. Cell wall", "B. Cytoplasm", "C. Cell membrane", "D. Nuclear envelope"]', 'C', 'The fluid mosaic model describes the cell membrane structure.', 'medium', 1, 60),
('q_wassce_bio_2023_10', 'topic_cell_biology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Which type of cell division produces gametes?', 'multiple_choice', '["A. Mitosis", "B. Meiosis", "C. Binary fission", "D. Budding"]', 'B', 'Meiosis produces haploid gametes for sexual reproduction.', 'easy', 1, 60),

-- Genetics (10 questions)
('q_wassce_bio_2023_11', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'DNA stands for:', 'multiple_choice', '["A. Deoxyribose nucleic acid", "B. Deoxyribonucleic acid", "C. Diribonucleic acid", "D. Deoxyribose nitrogen acid"]', 'B', 'DNA is deoxyribonucleic acid.', 'easy', 1, 60),
('q_wassce_bio_2023_12', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'The genotype Aa represents:', 'multiple_choice', '["A. Homozygous dominant", "B. Homozygous recessive", "C. Heterozygous", "D. Co-dominant"]', 'C', 'Aa has two different alleles, making it heterozygous.', 'easy', 1, 60),
('q_wassce_bio_2023_13', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'In humans, sex is determined by:', 'multiple_choice', '["A. X chromosome from mother", "B. Y chromosome from father", "C. Number of autosomes", "D. Environmental factors"]', 'B', 'Males contribute either X or Y; Y determines male sex.', 'medium', 1, 60),
('q_wassce_bio_2023_14', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'A mutation is:', 'multiple_choice', '["A. Normal cell division", "B. A change in DNA sequence", "C. Protein synthesis", "D. Cell differentiation"]', 'B', 'Mutations are permanent changes in the DNA sequence.', 'easy', 1, 60),
('q_wassce_bio_2023_15', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'The ratio 3:1 in Mendel''s experiments represents:', 'multiple_choice', '["A. Genotypic ratio", "B. Phenotypic ratio in F2", "C. Sex ratio", "D. Mutation rate"]', 'B', 'The 3:1 ratio is the phenotypic ratio in F2 monohybrid crosses.', 'medium', 1, 90),
('q_wassce_bio_2023_16', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'Sickle cell disease is caused by:', 'multiple_choice', '["A. Bacterial infection", "B. Viral infection", "C. Gene mutation", "D. Nutritional deficiency"]', 'C', 'Sickle cell is caused by a point mutation in the hemoglobin gene.', 'easy', 1, 60),
('q_wassce_bio_2023_17', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'The base that pairs with adenine in DNA is:', 'multiple_choice', '["A. Guanine", "B. Cytosine", "C. Thymine", "D. Uracil"]', 'C', 'Adenine pairs with thymine (A-T) in DNA.', 'easy', 1, 60),
('q_wassce_bio_2023_18', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'Crossing over occurs during:', 'multiple_choice', '["A. Mitosis", "B. Meiosis I", "C. Meiosis II", "D. Interphase"]', 'B', 'Crossing over occurs during prophase I of meiosis.', 'medium', 1, 90),
('q_wassce_bio_2023_19', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'A pedigree chart is used to:', 'multiple_choice', '["A. Classify organisms", "B. Trace inheritance patterns", "C. Count chromosomes", "D. Measure DNA"]', 'B', 'Pedigree charts trace inheritance patterns in families.', 'easy', 1, 60),
('q_wassce_bio_2023_20', 'topic_genetics', 'subj_biology', 'pp_wassce_bio_2023_1', 'The number of chromosomes in human body cells is:', 'multiple_choice', '["A. 23", "B. 44", "C. 46", "D. 48"]', 'C', 'Human body cells contain 46 chromosomes (23 pairs).', 'easy', 1, 60),

-- Ecology (10 questions)
('q_wassce_bio_2023_21', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'A community of living organisms and their physical environment is called:', 'multiple_choice', '["A. Population", "B. Ecosystem", "C. Biome", "D. Habitat"]', 'B', 'An ecosystem includes both biotic and abiotic components.', 'easy', 1, 60),
('q_wassce_bio_2023_22', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Organisms that make their own food are called:', 'multiple_choice', '["A. Consumers", "B. Decomposers", "C. Producers", "D. Herbivores"]', 'C', 'Producers (autotrophs) make their own food through photosynthesis.', 'easy', 1, 60),
('q_wassce_bio_2023_23', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The nitrogen cycle involves all EXCEPT:', 'multiple_choice', '["A. Nitrogen fixation", "B. Nitrification", "C. Photosynthesis", "D. Denitrification"]', 'C', 'Photosynthesis is part of the carbon cycle, not nitrogen cycle.', 'medium', 1, 90),
('q_wassce_bio_2023_24', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'A relationship where one organism benefits and the other is unaffected is:', 'multiple_choice', '["A. Parasitism", "B. Mutualism", "C. Commensalism", "D. Competition"]', 'C', 'In commensalism, one benefits while the other is neither helped nor harmed.', 'easy', 1, 60),
('q_wassce_bio_2023_25', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Primary succession occurs on:', 'multiple_choice', '["A. Burned forests", "B. Bare rock", "C. Abandoned farmland", "D. Flooded areas"]', 'B', 'Primary succession starts on bare, lifeless substrates like rock.', 'medium', 1, 60),
('q_wassce_bio_2023_26', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The greenhouse effect is caused mainly by:', 'multiple_choice', '["A. Oxygen", "B. Nitrogen", "C. Carbon dioxide", "D. Hydrogen"]', 'C', 'CO2 is a major greenhouse gas trapping heat in the atmosphere.', 'easy', 1, 60),
('q_wassce_bio_2023_27', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'In a food chain, energy transfer between trophic levels is approximately:', 'multiple_choice', '["A. 100%", "B. 50%", "C. 10%", "D. 1%"]', 'C', 'Only about 10% of energy transfers between trophic levels.', 'medium', 1, 90),
('q_wassce_bio_2023_28', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Biological oxygen demand (BOD) indicates:', 'multiple_choice', '["A. Air quality", "B. Water pollution level", "C. Soil fertility", "D. Temperature"]', 'B', 'High BOD indicates organic pollution in water.', 'medium', 1, 60),
('q_wassce_bio_2023_29', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Lichens are examples of:', 'multiple_choice', '["A. Parasitism", "B. Mutualism", "C. Predation", "D. Competition"]', 'B', 'Lichens are mutualistic associations between fungi and algae.', 'easy', 1, 60),
('q_wassce_bio_2023_30', 'topic_ecology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Decomposers in an ecosystem are important because they:', 'multiple_choice', '["A. Produce oxygen", "B. Recycle nutrients", "C. Fix nitrogen", "D. Produce food"]', 'B', 'Decomposers break down dead matter and recycle nutrients.', 'easy', 1, 60),

-- Human Physiology (10 questions)
('q_wassce_bio_2023_31', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The hormone that regulates blood sugar is:', 'multiple_choice', '["A. Thyroxine", "B. Adrenaline", "C. Insulin", "D. Testosterone"]', 'C', 'Insulin lowers blood glucose levels.', 'easy', 1, 60),
('q_wassce_bio_2023_32', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Gas exchange in humans occurs in the:', 'multiple_choice', '["A. Bronchi", "B. Trachea", "C. Alveoli", "D. Bronchioles"]', 'C', 'Alveoli are the sites of gas exchange in the lungs.', 'easy', 1, 60),
('q_wassce_bio_2023_33', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The part of the brain that controls balance is the:', 'multiple_choice', '["A. Cerebrum", "B. Cerebellum", "C. Medulla", "D. Hypothalamus"]', 'B', 'The cerebellum coordinates balance and movement.', 'easy', 1, 60),
('q_wassce_bio_2023_34', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Bile is produced by the:', 'multiple_choice', '["A. Pancreas", "B. Gallbladder", "C. Liver", "D. Stomach"]', 'C', 'The liver produces bile; the gallbladder stores it.', 'easy', 1, 60),
('q_wassce_bio_2023_35', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The blood type that is the universal donor is:', 'multiple_choice', '["A. A", "B. B", "C. AB", "D. O"]', 'D', 'Type O negative is the universal donor.', 'easy', 1, 60),
('q_wassce_bio_2023_36', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The functional unit of the kidney is the:', 'multiple_choice', '["A. Neuron", "B. Nephron", "C. Alveolus", "D. Villus"]', 'B', 'Nephrons are the functional units of the kidney.', 'easy', 1, 60),
('q_wassce_bio_2023_37', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The cardiac cycle consists of:', 'multiple_choice', '["A. One contraction only", "B. Systole and diastole", "C. Inspiration and expiration", "D. Absorption and secretion"]', 'B', 'The cardiac cycle involves systole (contraction) and diastole (relaxation).', 'medium', 1, 60),
('q_wassce_bio_2023_38', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Pepsin works best in:', 'multiple_choice', '["A. Alkaline conditions", "B. Neutral conditions", "C. Acidic conditions", "D. Any condition"]', 'C', 'Pepsin is optimally active in the acidic environment of the stomach.', 'easy', 1, 60),
('q_wassce_bio_2023_39', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'Red blood cells are produced in the:', 'multiple_choice', '["A. Liver", "B. Spleen", "C. Bone marrow", "D. Lymph nodes"]', 'C', 'Red blood cells are produced in the bone marrow.', 'easy', 1, 60),
('q_wassce_bio_2023_40', 'topic_human_physiology', 'subj_biology', 'pp_wassce_bio_2023_1', 'The reflex arc involves:', 'multiple_choice', '["A. Only sensory neurons", "B. Only motor neurons", "C. Sensory, relay, and motor neurons", "D. Only the brain"]', 'C', 'A reflex arc includes sensory, relay (interneuron), and motor neurons.', 'medium', 1, 90),

-- Evolution and Classification (10 questions)
('q_wassce_bio_2023_41', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'The scientist who proposed the theory of natural selection was:', 'multiple_choice', '["A. Mendel", "B. Darwin", "C. Lamarck", "D. Watson"]', 'B', 'Charles Darwin proposed the theory of natural selection.', 'easy', 1, 60),
('q_wassce_bio_2023_42', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Homologous structures indicate:', 'multiple_choice', '["A. Similar function", "B. Common ancestry", "C. Convergent evolution", "D. No relationship"]', 'B', 'Homologous structures suggest common evolutionary origin.', 'medium', 1, 60),
('q_wassce_bio_2023_43', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Fossils are evidence of:', 'multiple_choice', '["A. Current climate", "B. Past life forms", "C. Future evolution", "D. Soil composition"]', 'B', 'Fossils are preserved remains of past organisms.', 'easy', 1, 60),
('q_wassce_bio_2023_44', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'The binomial nomenclature system was developed by:', 'multiple_choice', '["A. Darwin", "B. Mendel", "C. Linnaeus", "D. Pasteur"]', 'C', 'Carl Linnaeus developed the binomial naming system.', 'easy', 1, 60),
('q_wassce_bio_2023_45', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Organisms in the same genus must also be in the same:', 'multiple_choice', '["A. Species", "B. Family", "C. Order", "D. Kingdom only"]', 'B', 'Genus is within family in the taxonomic hierarchy.', 'medium', 1, 90),
('q_wassce_bio_2023_46', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Vestigial organs provide evidence for:', 'multiple_choice', '["A. Creation", "B. Evolution", "C. Genetic engineering", "D. Mutation only"]', 'B', 'Vestigial structures are evolutionary remnants.', 'easy', 1, 60),
('q_wassce_bio_2023_47', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Which kingdom includes bacteria?', 'multiple_choice', '["A. Protista", "B. Fungi", "C. Monera", "D. Plantae"]', 'C', 'Bacteria belong to Kingdom Monera (or Prokaryotae).', 'easy', 1, 60),
('q_wassce_bio_2023_48', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Natural selection acts on:', 'multiple_choice', '["A. Genotype only", "B. Phenotype", "C. DNA only", "D. RNA only"]', 'B', 'Natural selection acts on phenotypic traits.', 'medium', 1, 60),
('q_wassce_bio_2023_49', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Speciation is the formation of:', 'multiple_choice', '["A. New individuals", "B. New species", "C. New cells", "D. New organs"]', 'B', 'Speciation is the evolutionary process forming new species.', 'easy', 1, 60),
('q_wassce_bio_2023_50', 'topic_evolution', 'subj_biology', 'pp_wassce_bio_2023_1', 'Adaptive radiation refers to:', 'multiple_choice', '["A. Extinction of species", "B. Evolution of many species from one ancestor", "C. Nuclear radiation effects", "D. Climate change"]', 'B', 'Adaptive radiation is diversification from a common ancestor.', 'medium', 1, 90);
